findings.fix:
lifecycle {
  precondition {
    condition     = startswith(var.zone, "${var.region}-")
    error_message = "var.zone must be a zone in var.region"
  }
}

output "template_self_link_unique" {
  value       = google_compute_region_instance_template.main.self_link_unique
  description = "Unique self-link of the template revision, for pinning managed instance groups"
}
